package radio

import (
	"bytes"
	"io"
	"math/rand"
	"os"
	"path/filepath"
	"testing"
	"testing/iotest"
)

// fixtureBytes returns a file generated by make fixtures in the decoder's
// testdata, skipping without it.
func fixtureBytes(t *testing.T, name string) []byte {
	t.Helper()
	path := filepath.Join("..", "audio", "decode", "testdata", name)
	b, err := os.ReadFile(path)
	if err != nil {
		t.Skipf("%s is missing; run make fixtures", path)
	}
	return b
}

func header(n int, protectionAbsent bool) []byte {
	b := []byte{0xFF, 0xF1, 0x50, byte(n >> 11 & 3), byte(n >> 3), byte(n&7) << 5, 0xFC}
	if !protectionAbsent {
		b[1] = 0xF0
	}
	return b
}

func TestADTSFrame(t *testing.T) {
	if n := adtsFrame(header(400, true)); n != 400 {
		t.Errorf("7-byte header, length 400: got %d", n)
	}
	if n := adtsFrame(header(8, false)); n != 0 {
		t.Errorf("CRC header, length 8: got %d, want 0", n)
	}
	if n := adtsFrame(header(9, false)); n != 9 {
		t.Errorf("CRC header, length 9: got %d", n)
	}
	b := header(400, true)
	b[1] = 0xF3
	if n := adtsFrame(b); n != 0 {
		t.Errorf("layer bits set: got %d", n)
	}
	b = header(400, true)
	b[2] = 13 << 2
	if n := adtsFrame(b); n != 0 {
		t.Errorf("sampling index 13: got %d", n)
	}
	b = header(400, true)
	b[0] = 0xFE
	if n := adtsFrame(b); n != 0 {
		t.Errorf("bad sync: got %d", n)
	}
	if n := adtsFrame(b[:6]); n != 0 {
		t.Errorf("short input: got %d", n)
	}
}

// walk splits an ADTS stream with no junk into its frames.
func walk(t *testing.T, b []byte) [][]byte {
	t.Helper()
	var frames [][]byte
	for len(b) > 0 {
		n := adtsFrame(b)
		if n == 0 || n > len(b) {
			break
		}
		frames = append(frames, b[:n])
		b = b[n:]
	}
	if len(frames) == 0 {
		t.Fatal("no frames in the file")
	}
	return frames
}

func readFrames(t *testing.T, r io.Reader) [][]byte {
	t.Helper()
	fr := newADTSReader(r)
	var got [][]byte
	for {
		f, err := fr.Next()
		if err == io.EOF {
			return got
		}
		if err != nil {
			t.Fatal(err)
		}
		got = append(got, bytes.Clone(f))
	}
}

func sameFrames(t *testing.T, got, want [][]byte) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("got %d frames, want %d", len(got), len(want))
	}
	for i := range want {
		if !bytes.Equal(got[i], want[i]) {
			t.Fatalf("frame %d differs", i)
		}
	}
}

func TestADTSReader(t *testing.T) {
	file := fixtureBytes(t, "stream-44100.aac")
	want := walk(t, file)
	t.Run("one byte at a time", func(t *testing.T) {
		sameFrames(t, readFrames(t, iotest.OneByteReader(bytes.NewReader(file))), want)
	})
	t.Run("junk in front", func(t *testing.T) {
		junk := bytes.Repeat([]byte{0x12}, 1000)
		sameFrames(t, readFrames(t, bytes.NewReader(append(junk, file...))), want)
	})
	t.Run("false sync in the junk", func(t *testing.T) {
		junk := bytes.Repeat([]byte{0x12}, 1000)
		junk[500], junk[501] = 0xFF, 0xF1
		sameFrames(t, readFrames(t, bytes.NewReader(append(junk, file...))), want)
	})
}

func TestSniff(t *testing.T) {
	mp3File := fixtureBytes(t, "stream-44100.mp3")
	aacFile := fixtureBytes(t, "stream-44100.aac")
	if c := sniff(mp3File); c != mp3 {
		t.Errorf("mp3 fixture: %v", c)
	}
	if c := sniff(aacFile); c != aac {
		t.Errorf("aac fixture: %v", c)
	}
	if c := sniff([]byte("ID3 and anything")); c != mp3 {
		t.Errorf("ID3: %v", c)
	}
	noise := make([]byte, 8<<10)
	rand.New(rand.NewSource(1)).Read(noise)
	if c := sniff(noise); c != unknown {
		t.Errorf("noise: %v", c)
	}
}

func TestCodecOf(t *testing.T) {
	cases := []struct {
		in       string
		c        codec
		playlist bool
	}{
		{"audio/mpeg", mp3, false},
		{"audio/mp3", mp3, false},
		{"audio/aac", aac, false},
		{"audio/aacp", aac, false},
		{"audio/x-aac", aac, false},
		{"audio/aacp; charset=x", aac, false},
		{"audio/x-scpls", unknown, true},
		{"audio/x-mpegurl", unknown, true},
		{"application/vnd.apple.mpegurl", unknown, true},
		{"text/html", unknown, true},
		{"application/octet-stream", unknown, false},
		{"", unknown, false},
	}
	for _, tc := range cases {
		c, playlist := codecOf(tc.in)
		if c != tc.c || playlist != tc.playlist {
			t.Errorf("codecOf(%q) = %v, %v; want %v, %v", tc.in, c, playlist, tc.c, tc.playlist)
		}
	}
}
